if(s==="\u0cad\u0cbe\u0ca6\u0ccd\u0cb0\u0caa\u0ca6")if(r===2)k.push(new A.cd("\u0cb8\u0ccd\u0cb5\u0cb0\u0ccd\u0ca3\u0c97\u0ccc\u0cb0\u0cbf \u0cb5\u0ccd\u0cb0\u0ca4 (\u0ca4\u0ca6\u0cbf\u0c97\u0cc6)","\u0cae\u0cb9\u0cbf\u0cb3\u0cc6\u0caf\u0cb0\u0cc1 \u0cb8\u0ccc\u0cad\u0cbe\u0c97\u0ccd\u0caf\u0c95\u0ccd\u0c95\u0cbe\u0c97\u0cbf \u0c86\u0c9a\u0cb0\u0cbf\u0cb8\u0cc1\u0cb5 \u0caa\u0cbe\u0cb0\u0ccd\u0cb5\u0ca4\u0cbf \u0ca6\u0cc7\u0cb5\u0cbf\u0caf \u0cb5\u0ccd\u0cb0\u0ca4.","\u0cad\u0cbe\u0ca6\u0ccd\u0cb0\u0cc7 \u0cae\u0cbe\u0cb8\u0cbf \u0cb8\u0cbf\u0ca4\u0cc7 \u0caa\u0c95\u0ccd\u0cb7\u0cc7 \u0ca4\u0cc3\u0ca4\u0cc0\u0caf\u0cbe\u0caf\u0cbe\u0c82 \u0cb8\u0cc1\u0cb6\u0ccb\u0cad\u0ca8\u0cc7 |\\n\u0cb8\u0c82\u0caa\u0cc2\u0c9c\u0ccd\u0caf\u0cbe \u0caa\u0cbe\u0cb0\u0ccd\u0cb5\u0ca4\u0cc0 \u0ca6\u0cc7\u0cb5\u0cc0 \u0cb8\u0ccc\u0cad\u0cbe\u0c97\u0ccd\u0caf\u0cbe\u0cb0\u0ccb\u0c97\u0ccd\u0caf\u0cb5\u0cb0\u0ccd\u0ca7\u0cbf\u0ca8\u0cc0 ||","\u0cad\u0cbe\u0ca6\u0ccd\u0cb0\u0caa\u0ca6 \u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0ca4\u0cc3\u0ca4\u0cc0\u0caf\u0cbe \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0ccb\u0ca6\u0caf \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1. \u0cb8\u0ccd\u0ca4\u0ccd\u0cb0\u0cc0\u0caf\u0cb0\u0cc1 \u0c89\u0caa\u0cb5\u0cbe\u0cb8 \u0cae\u0cbe\u0ca1\u0cbf \u0caa\u0cbe\u0cb0\u0ccd\u0cb5\u0ca4\u0cbf \u0ca6\u0cc7\u0cb5\u0cbf\u0c97\u0cc6 \u0ce7\u0cec \u0cb6\u0cc3\u0c82\u0c97\u0cbe\u0cb0 \u0caa\u0cc2\u0c9c\u0cc6. \u0cae\u0cc1\u0ca4\u0ccd\u0ca4\u0cc8\u0ca6\u0cc6\u0caf\u0cb0\u0cbf\u0c97\u0cc6 \u0cac\u0cbe\u0c97\u0cbf\u0ca8.","\u0cb5\u0ccd\u0cb0\u0ca4 \u0cb0\u0ca4\u0ccd\u0ca8\u0cbe\u0cb5\u0cb3\u0cbf"))
else if(r===3)k.push(new A.cd("\u0cb5\u0cb0\u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0cbf \u0cb5\u0cbf\u0ca8\u0cbe\u0caf\u0c95 \u0c9a\u0ccc\u0ca4\u0cbf (\u0c97\u0ca3\u0cc7\u0cb6 \u0c9a\u0ca4\u0cc1\u0cb0\u0ccd\u0ca5\u0cbf)","\u0cb5\u0cbf\u0c98\u0ccd\u0ca8\u0ca8\u0cbf\u0cb5\u0cbe\u0cb0\u0c95 \u0cae\u0cb9\u0cbe\u0c97\u0ca3\u0caa\u0ca4\u0cbf\u0caf \u0c85\u0cb5\u0ca4\u0cbe\u0cb0 \u0ca6\u0cbf\u0ca8.","\u0cad\u0cbe\u0ca6\u0ccd\u0cb0\u0cb6\u0cc1\u0c95\u0ccd\u0cb2\u0c9a\u0ca4\u0cc1\u0cb0\u0ccd\u0ca5\u0ccd\u0caf\u0cbe\u0c82 \u0ca4\u0cc1 \u0caf\u0ca8\u0ccd\u0cae\u0cb9\u0cbe\u0c97\u0ca3\u0caa\u0ca4\u0cc7\u0cb0\u0ccd\u0ca6\u0cbf\u0ca8\u0cae\u0ccd |","\u0cad\u0cbe\u0ca6\u0ccd\u0cb0\u0caa\u0ca6 \u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0c9a\u0ca4\u0cc1\u0cb0\u0ccd\u0ca5\u0cbf \u0cae\u0ca7\u0ccd\u0caf\u0cbe\u0cb9\u0ccd\u0ca8 \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1. \u0cae\u0cc3\u0ca4\u0ccd\u0ca4\u0cbf\u0c95\u0cbe \u0c97\u0ca3\u0caa\u0ca4\u0cbf \u0cb8\u0ccd\u0ca5\u0cbe\u0caa\u0cbf\u0cb8\u0cbf \u0caa\u0ccd\u0cb0\u0cbe\u0ca3\u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0cb7\u0ccd\u0ca0\u0cc6. \u0cae\u0ccb\u0ca6\u0c95 \u0ca8\u0cc8\u0cb5\u0cc7\u0ca6\u0ccd\u0caf. \u0c9a\u0c82\u0ca6\u0ccd\u0cb0 \u0ca6\u0cb0\u0ccd\u0cb6\u0ca8 \u0cb5\u0cb0\u0ccd\u0c9c\u0ccd\u0caf.",n))
else if(r===4)k.push(new A.cd("\u0c8b\u0cb7\u0cbf \u0caa\u0c82\u0c9a\u0cae\u0cbf","\u0cb8\u0caa\u0ccd\u0ca4 \u0c8b\u0cb7\u0cbf\u0c97\u0cb3 \u0c86\u0cb0\u0cbe\u0ca7\u0ca8\u0cc6. \u0c85\u0c9c\u0ccd\u0c9e\u0cbe\u0ca4 \u0caa\u0cbe\u0caa \u0caa\u0cb0\u0cbf\u0cb9\u0cbe\u0cb2\u0c95 \u0cb5\u0ccd\u0cb0\u0ca4.","\u0cad\u0cbe\u0ca6\u0ccd\u0cb0\u0cc7 \u0cb6\u0cc1\u0c95\u0ccd\u0cb2\u0cc7 \u0caa\u0c82\u0c9a\u0cae\u0ccd\u0caf\u0cbe\u0c82 \u0ca4\u0cc1 \u0cb8\u0caa\u0ccd\u0ca4\u0cb0\u0ccd\u0cb7\u0cc0\u0ca8\u0ccd \u0caa\u0cc2\u0c9c\u0caf\u0cc7\u0ca4\u0ccd \u0cb8\u0ca6\u0cbe |\\n\u0c85\u0c9c\u0ccd\u0c9e\u0cbe\u0ca4\u0caa\u0cbe\u0caa\u0cb6\u0cc1\u0ca6\u0ccd\u0ca7\u0ccd\u0caf\u0cb0\u0ccd\u0ca5\u0c82 \u0cb5\u0ccd\u0cb0\u0ca4\u0cae\u0cc7\u0ca4\u0ca4\u0ccd \u0cb8\u0cae\u0cbe\u0c9a\u0cb0\u0cc7\u0ca4\u0ccd ||","\u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0caa\u0c82\u0c9a\u0cae\u0cbf \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0ccb\u0ca6\u0caf \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1. \u0cb8\u0caa\u0ccd\u0ca4 \u0c8b\u0cb7\u0cbf\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0caa\u0cc2\u0c9c\u0cbf\u0cb8\u0cac\u0cc7\u0c95\u0cc1. \u0c85\u0c9c\u0ccd\u0c9e\u0cbe\u0ca4 \u0caa\u0cbe\u0caa \u0cb6\u0cc1\u0ca6\u0ccd\u0ca7\u0cbf\u0c97\u0cbe\u0c97\u0cbf \u0cb5\u0ccd\u0cb0\u0ca4 \u0c86\u0c9a\u0cb0\u0cbf\u0cb8\u0cac\u0cc7\u0c95\u0cc1.","\u0ca7\u0cb0\u0ccd\u0cae\u0cb8\u0cbf\u0c82\u0ca7\u0cc1 - \u0cad\u0cbe\u0ca6\u0ccd\u0cb0\u0caa\u0ca6"))
else if(r===13)k.push(new A.cd("\u0c85\u0ca8\u0c82\u0ca4 \u0c9a\u0ca4\u0cc1\u0cb0\u0ccd\u0ca6\u0cb6\u0cbf (\u0c97\u0ca3\u0cc7\u0cb6 \u0cb5\u0cbf\u0cb8\u0cb0\u0ccd\u0c9c\u0ca8)","\u0c97\u0ca3\u0cc7\u0cb6 \u0cb5\u0cbf\u0cb8\u0cb0\u0ccd\u0c9c\u0ca8\u0cc6 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0c85\u0ca8\u0c82\u0ca4 \u0caa\u0ca6\u0ccd\u0cae\u0ca8\u0cbe\u0cad \u0cb5\u0ccd\u0cb0\u0ca4.","\u0cad\u0cbe\u0ca6\u0ccd\u0cb0\u0caa\u0ca6 \u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0c9a\u0ca4\u0cc1\u0cb0\u0ccd\u0ca6\u0cb6\u0ccd\u0caf\u0cbe\u0c82 \u0c85\u0ca8\u0c82\u0ca4\u0cb5\u0ccd\u0cb0\u0ca4\u0cae\u0cbe\u0c9a\u0cb0\u0cc7\u0ca4\u0ccd |\\n\u0c97\u0ca3\u0cc7\u0cb6\u0c82 \u0cb5\u0cbf\u0cb8\u0cb0\u0ccd\u0c9c\u0caf\u0cc7\u0ca4\u0ccd \u0cad\u0c95\u0ccd\u0ca4\u0ccd\u0caf\u0cbe \u0caa\u0cc1\u0ca8\u0cb0\u0cbe\u0c97\u0cae\u0ca8\u0cbe\u0caf \u0c9a ||","\u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0c9a\u0ca4\u0cc1\u0cb0\u0ccd\u0ca6\u0cb6\u0cbf \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0ccb\u0ca6\u0caf \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1. \u0c97\u0ca3\u0cc7\u0cb6 \u0cb5\u0cbf\u0cb8\u0cb0\u0ccd\u0c9c\u0ca8\u0cc6 \u0cae\u0ca7\u0ccd\u0caf\u0cbe\u0cb9\u0ccd\u0ca8/\u0cb8\u0c82\u0c9c\u0cc6 \u0cae\u0cbe\u0ca1\u0cac\u0cc7\u0c95\u0cc1. \u0c85\u0ca8\u0c82\u0ca4 \u0caa\u0ca6\u0ccd\u0cae\u0ca8\u0cbe\u0cad \u0cb5\u0ccd\u0cb0\u0ca4 \u0c86\u0c9a\u0cb0\u0cbf\u0cb8\u0cac\u0cc7\u0c95\u0cc1.",n))
else if(r===14)k.push(new A.cd("\u0c85\u0ca8\u0c82\u0ca4 \u0caa\u0ca6\u0ccd\u0cae\u0ca8\u0cbe\u0cad \u0cb5\u0ccd\u0cb0\u0ca4 / \u0cae\u0cb9\u0cbe\u0cb2\u0caf\u0cbe\u0cb0\u0c82\u0cad","\u0c85\u0ca8\u0c82\u0ca4\u0ca8 (\u0cb5\u0cbf\u0cb7\u0ccd\u0ca3\u0cc1\u0cb5\u0cbf\u0ca8) \u0c86\u0cb0\u0cbe\u0ca7\u0ca8\u0cc6. \u0caa\u0cbf\u0ca4\u0cc3\u0caa\u0c95\u0ccd\u0cb7\u0ca6 \u0c86\u0cb0\u0c82\u0cad.","\u0cad\u0cbe\u0ca6\u0ccd\u0cb0\u0caa\u0ca6 \u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0c9a\u0ca4\u0cc1\u0cb0\u0ccd\u0ca6\u0cb6\u0ccd\u0caf\u0cbe\u0c82 \u0c85\u0ca8\u0c82\u0ca4\u0cb5\u0ccd\u0cb0\u0ca4\u0cae\u0cbe\u0c9a\u0cb0\u0cc7\u0ca4\u0ccd |","\u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0c9a\u0ca4\u0cc1\u0cb0\u0ccd\u0ca6\u0cb6\u0cbf \u0c85\u0ca5\u0cb5\u0cbe \u0caa\u0ccc\u0cb0\u0ccd\u0ca3\u0cbf\u0cae\u0cbe \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0ccb\u0ca6\u0caf \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf. \u0c85\u0ca8\u0c82\u0ca4 \u0ca6\u0cc7\u0cb5\u0cb0\u0cbf\u0c97\u0cc6 \u0ce7\u0cea \u0c97\u0c82\u0c9f\u0cc1 \u0ca6\u0cbe\u0cb0 \u0c95\u0c9f\u0ccd\u0c9f\u0cbf \u0caa\u0cc2\u0c9c\u0cbf\u0cb8\u0cac\u0cc7\u0c95\u0cc1. \u0caa\u0cbf\u0ca4\u0cc3\u0caa\u0c95\u0ccd\u0cb7 \u0c86\u0cb0\u0c82\u0cad.",p))
else if(r===29)k.push(new A.cd("\u0cae\u0cb9\u0cbe\u0cb2\u0caf \u0c85\u0cae\u0cbe\u0cb5\u0cbe\u0cb8\u0ccd\u0caf\u0cc6","\u0caa\u0cbf\u0ca4\u0cc3 \u0caa\u0c95\u0ccd\u0cb7\u0ca6 \u0cae\u0cc1\u0c95\u0ccd\u0ca4\u0cbe\u0caf. \u0cb8\u0cb0\u0ccd\u0cb5 \u0caa\u0cbf\u0ca4\u0cc3\u0c97\u0cb3\u0cbf\u0c97\u0cc2 \u0ca4\u0cb0\u0ccd\u0caa\u0ca3 \u0cac\u0cbf\u0ca1\u0cc1\u0cb5 \u0ca6\u0cbf\u0ca8.","\u0c86\u0caf\u0cc1\u0c83 \u0caa\u0ccd\u0cb0\u0c9c\u0cbe\u0c82 \u0ca7\u0ca8\u0c82 \u0cb5\u0cbf\u0ca6\u0ccd\u0caf\u0cbe\u0c82 \u0cb8\u0ccd\u0cb5\u0cb0\u0ccd\u0c97\u0c82 \u0cae\u0ccb\u0c95\u0ccd\u0cb7\u0c82 \u0cb8\u0cc1\u0c96\u0cbe\u0ca8\u0cbf \u0c9a |\\n\u0caa\u0ccd\u0cb0\u0caf\u0c9a\u0ccd\u0c9b\u0ca8\u0ccd\u0ca4\u0cbf \u0ca4\u0ca5\u0cbe \u0cb0\u0cbe\u0c9c\u0ccd\u0caf\u0c82 \u0caa\u0cbf\u0ca4\u0cb0\u0c83 \u0cb6\u0ccd\u0cb0\u0cbe\u0ca6\u0ccd\u0ca7\u0ca4\u0cb0\u0ccd\u0caa\u0cbf\u0ca4\u0cbe\u0c83 ||","\u0c85\u0cae\u0cbe\u0cb5\u0cbe\u0cb8\u0ccd\u0caf\u0cbe \u0ca4\u0cbf\u0ca5\u0cbf \u0c85\u0caa\u0cb0\u0cbe\u0cb9\u0ccd\u0ca3 \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1. \u0cb8\u0cb0\u0ccd\u0cb5 \u0caa\u0cbf\u0ca4\u0cc3\u0c97\u0cb3\u0cbf\u0c97\u0cc2 \u0ca4\u0cb0\u0ccd\u0caa\u0ca3-\u0cb6\u0ccd\u0cb0\u0cbe\u0ca6\u0ccd\u0ca7 \u0cae\u0cbe\u0ca1\u0cac\u0cc7\u0c95\u0cc1. \u0c87\u0ca6\u0cc1 \u0caa\u0cbf\u0ca4\u0cc3\u0caa\u0c95\u0ccd\u0cb7\u0ca6 \u0c95\u0cca\u0ca8\u0cc6\u0caf \u0ca6\u0cbf\u0ca8. \u0c8e\u0cb3\u0ccd\u0cb3\u0cc1-\u0ca8\u0cc0\u0cb0\u0cbf\u0ca8\u0cbf\u0c82\u0ca6 \u0ca4\u0cb0\u0ccd\u0caa\u0ca3.","\u0caf\u0cbe\u0c9c\u0ccd\u0c9e\u0cb5\u0cb2\u0ccd\u0c95\u0ccd\u0caf \u0cb8\u0ccd\u0cae\u0cc3\u0ca4\u0cbf"))
if(s==="\u0c86\u0cb6\u0ccd\u0cb5\u0cbf\u0ca8")if(r===0)k.push(new A.cd("\u0cb6\u0cb0\u0ca8\u0ccd\u0ca8\u0cb5\u0cb0\u0cbe\u0ca4\u0ccd\u0cb0\u0cbf \u0c86\u0cb0\u0c82\u0cad / \u0c98\u0c9f\u0cb8\u0ccd\u0ca5\u0cbe\u0caa\u0ca8\u0cc6","\u0c92\u0c82\u0cac\u0ca4\u0ccd\u0ca4\u0cc1 \u0ca6\u0cbf\u0ca8\u0c97\u0cb3 \u0c95\u0cbe\u0cb2 \u0c9c\u0c97\u0ca8\u0ccd\u0cae\u0cbe\u0ca4\u0cc6\u0caf \u0c86\u0cb0\u0cbe\u0ca7\u0ca8\u0cc6. \u0c98\u0c9f\u0cb8\u0ccd\u0ca5\u0cbe\u0caa\u0ca8\u0cc6, \u0c9a\u0c82\u0ca1\u0cc0\u0caa\u0cbe\u0ca0, \u0c95\u0cc1\u0cae\u0cbe\u0cb0\u0cc0 \u0caa\u0cc2\u0c9c\u0cc6 \u0cb5\u0cbf\u0cb6\u0cc7\u0cb7.","\u0c9c\u0caf\u0c82\u0ca4\u0cc0 \u0cae\u0c82\u0c97\u0cb2\u0cbe \u0c95\u0cbe\u0cb3\u0cc0 \u0cad\u0ca6\u0ccd\u0cb0\u0c95\u0cbe\u0cb2\u0cc0 \u0c95\u0caa\u0cbe\u0cb2\u0cbf\u0ca8\u0cc0 |\\n\u0ca6\u0cc1\u0cb0\u0ccd\u0c97\u0cbe \u0c95\u0ccd\u0cb7\u0cae\u0cbe \u0cb6\u0cbf\u0cb5\u0cbe \u0ca7\u0cbe\u0ca4\u0ccd\u0cb0\u0cc0 \u0cb8\u0ccd\u0cb5\u0ca7\u0cbe \u0cb8\u0ccd\u0cb5\u0cbe\u0cb9\u0cbe \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 ||","\u0c86\u0cb6\u0ccd\u0cb5\u0cbf\u0ca8 \u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0caa\u0ca6\u0cc6 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0ccb\u0ca6\u0caf \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1. \u0c98\u0c9f\u0cb8\u0ccd\u0ca5\u0cbe\u0caa\u0ca8\u0cc6 \u0cae\u0cbe\u0ca1\u0cbf \u0cef \u0ca6\u0cbf\u0ca8 \u0ca6\u0cc7\u0cb5\u0cbf \u0c86\u0cb0\u0cbe\u0ca7\u0ca8\u0cc6. \u0caa\u0ccd\u0cb0\u0ca4\u0cbf\u0ca6\u0cbf\u0ca8 \u0c9a\u0c82\u0ca1\u0cc0\u0caa\u0cbe\u0ca0, \u0c95\u0cc1\u0cae\u0cbe\u0cb0\u0cc0 \u0caa\u0cc2\u0c9c\u0cc6. \u0c89\u0caa\u0cb5\u0cbe\u0cb8 \u0c85\u0ca5\u0cb5\u0cbe \u0cab\u0cb2\u0cbe\u0cb9\u0cbe\u0cb0.","\u0ca7\u0cb0\u0ccd\u0cae\u0cb8\u0cbf\u0c82\u0ca7\u0cc1 - \u0ca8\u0cb5\u0cb0\u0cbe\u0ca4\u0ccd\u0cb0\u0cbe\u0cb0\u0c82\u0cad \u0caa\u0ccd\u0cb0\u0caf\u0ccb\u0c97 (\u0caa\u0cc1. \u0ce7\u0ce9\u0ceb)"))
else if(r===4)k.push(new A.cd("\u0cb2\u0cb2\u0cbf\u0ca4\u0cbe \u0caa\u0c82\u0c9a\u0cae\u0cbf / \u0c89\u0caa\u0cbe\u0c82\u0c97\u0cb2\u0cb2\u0cbf\u0ca4\u0cbe \u0cb5\u0ccd\u0cb0\u0ca4","\u0ca8\u0cb5\u0cb0\u0cbe\u0ca4\u0ccd\u0cb0\u0cbf\u0caf \u0c90\u0ca6\u0ca8\u0cc6\u0caf \u0ca6\u0cbf\u0ca8. \u0cb2\u0cb2\u0cbf\u0ca4\u0cbe \u0ca6\u0cc7\u0cb5\u0cbf\u0caf \u0cb5\u0cbf\u0cb6\u0cc7\u0cb7 \u0c86\u0cb0\u0cbe\u0ca7\u0ca8\u0cc6.","\u0caa\u0c82\u0c9a\u0cae\u0ccd\u0caf\u0cbe\u0c82 \u0cb2\u0cb2\u0cbf\u0ca4\u0cbe\u0c82 \u0ca6\u0cc7\u0cb5\u0cc0\u0c82 \u0caa\u0cc2\u0c9c\u0caf\u0cc7\u0ca4\u0ccd \u0cb8\u0cb0\u0ccd\u0cb5\u0cb8\u0cbf\u0ca6\u0ccd\u0ca7\u0cbf\u0ca6\u0cbe\u0cae\u0ccd |\\n\u0c89\u0caa\u0cbe\u0c82\u0c97\u0cb2\u0cb2\u0cbf\u0ca4\u0cbe \u0cb5\u0ccd\u0cb0\u0ca4\u0c82 \u0c85\u0caa\u0cb0\u0cbe\u0cb9\u0ccd\u0ca3\u0cc7 \u0cb8\u0cae\u0cbe\u0c9a\u0cb0\u0cc7\u0ca4\u0ccd ||","\u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0caa\u0c82\u0c9a\u0cae\u0cbf \u0c85\u0caa\u0cb0\u0cbe\u0cb9\u0ccd\u0ca3 \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1. \u0c85\u0caa\u0cb0\u0cbe\u0cb9\u0ccd\u0ca3 \u0c95\u0cbe\u0cb2\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0c89\u0caa\u0cbe\u0c82\u0c97\u0cb2\u0cb2\u0cbf\u0ca4\u0cbe \u0cb5\u0ccd\u0cb0\u0ca4 \u0c86\u0c9a\u0cb0\u0cbf\u0cb8\u0cac\u0cc7\u0c95\u0cc1. \u0cb2\u0cb2\u0cbf\u0ca4\u0cbe \u0cb8\u0cb9\u0cb8\u0ccd\u0cb0\u0ca8\u0cbe\u0cae \u0caa\u0cbe\u0cb0\u0cbe\u0caf\u0ca3.","\u0ca7\u0cb0\u0ccd\u0cae\u0cb8\u0cbf\u0c82\u0ca7\u0cc1 - \u0c85\u0cb6\u0ccd\u0cb5\u0cbf\u0ca8 \u0cae\u0cbe\u0cb8 (\u0caa\u0cc1. \u0ce7\u0ce9\u0cef)"))
else if(r===6)k.push(new A.cd("\u0cb8\u0cb0\u0cb8\u0ccd\u0cb5\u0ca4\u0cc0 \u0caa\u0cc2\u0c9c\u0cc6 / \u0cb8\u0cb0\u0cb8\u0ccd\u0cb5\u0ca4\u0ccd\u0caf\u0cbe\u0cb5\u0cbe\u0cb9\u0ca8","\u0cb5\u0cbf\u0ca6\u0ccd\u0caf\u0cbe\u0ca6\u0cc7\u0cb5\u0ca4\u0cc6 \u0cb8\u0cb0\u0cb8\u0ccd\u0cb5\u0ca4\u0cbf\u0caf \u0c86\u0cb5\u0cbe\u0cb9\u0ca8\u0cc6 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0caa\u0cc2\u0c9c\u0cc6. \u0caa\u0cc1\u0cb8\u0ccd\u0ca4\u0c95 \u0caa\u0cc2\u0c9c\u0cc6 \u0cb5\u0cbf\u0cb6\u0cc7\u0cb7.","\u0cae\u0cc2\u0cb2\u0cc7 \u0caa\u0cc1\u0cb8\u0ccd\u0ca4\u0cb8\u0ccd\u0ca5\u0cbe\u0caa\u0ca8\u0c82 \u0ca6\u0cc7\u0cb5\u0ccd\u0caf\u0cbe\u0c83 \u0caa\u0cc2\u0cb0\u0ccd\u0cb5\u0cbe\u0cb7\u0cbe\u0ca2\u0cbe\u0cb8\u0cc1 \u0caa\u0cc2\u0c9c\u0ca8\u0cae\u0ccd |\\n\u0c89\u0ca4\u0ccd\u0ca4\u0cb0\u0cbe\u0cb8\u0cc1 \u0cac\u0cb2\u0cbf\u0c82 \u0ca6\u0ca6\u0ccd\u0caf\u0cbe\u0ca4\u0ccd \u0cb6\u0ccd\u0cb0\u0cb5\u0ca3\u0cc7\u0ca8 \u0cb5\u0cbf\u0cb8\u0cb0\u0ccd\u0c9c\u0caf\u0cc7\u0ca4\u0ccd ||","\u0cae\u0cc2\u0cb2\u0cbe \u0ca8\u0c95\u0ccd\u0cb7\u0ca4\u0ccd\u0cb0\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0caa\u0cc1\u0cb8\u0ccd\u0ca4\u0c95 \u0cb8\u0ccd\u0ca5\u0cbe\u0caa\u0ca8\u0cc6, \u0caa\u0cc2\u0cb0\u0ccd\u0cb5\u0cbe\u0cb7\u0cbe\u0ca2\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0caa\u0cc2\u0c9c\u0cc6, \u0c89\u0ca4\u0ccd\u0ca4\u0cb0\u0cbe\u0cb7\u0cbe\u0ca2\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0cac\u0cb2\u0cbf, \u0cb6\u0ccd\u0cb0\u0cb5\u0ca3\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0cb5\u0cbf\u0cb8\u0cb0\u0ccd\u0c9c\u0ca8\u0cc6. \u0cb8\u0cb0\u0cb8\u0ccd\u0cb5\u0ca4\u0cc0 \u0c86\u0cb5\u0cbe\u0cb9\u0ca8\u0cc6 \u0cae\u0cbe\u0ca1\u0cbf \u0cb5\u0cbf\u0ca6\u0ccd\u0caf\u0cbe \u0caa\u0ccd\u0cb0\u0cbe\u0caa\u0ccd\u0ca4\u0cbf\u0c97\u0cbe\u0c97\u0cbf \u0caa\u0ccd\u0cb0\u0cbe\u0cb0\u0ccd\u0ca5\u0ca8\u0cc6.","\u0ca7\u0cb0\u0ccd\u0cae\u0cb8\u0cbf\u0c82\u0ca7\u0cc1 - \u0cb8\u0cb0\u0cb8\u0ccd\u0cb5\u0ca4\u0ccd\u0caf\u0cbe\u0cb5\u0cbe\u0cb9\u0ca8 (\u0caa\u0cc1. \u0ce7\u0cea\u0ce6)"))
else if(r===7)k.push(new A.cd("\u0ca6\u0cc1\u0cb0\u0ccd\u0c97\u0cbe\u0cb7\u0ccd\u0c9f\u0cae\u0cc0 / \u0cae\u0cb9\u0cbe\u0cb7\u0ccd\u0c9f\u0cae\u0cc0","\u0ca8\u0cb5\u0cb0\u0cbe\u0ca4\u0ccd\u0cb0\u0cbf\u0caf \u0c8e\u0c82\u0c9f\u0ca8\u0cc6\u0caf \u0ca6\u0cbf\u0ca8. \u0ca6\u0cc1\u0cb0\u0ccd\u0c97\u0cbe \u0ca6\u0cc7\u0cb5\u0cbf\u0caf \u0cb5\u0cbf\u0cb6\u0cc7\u0cb7 \u0caa\u0cc2\u0c9c\u0cc6 \u0cae\u0ca4\u0ccd\u0ca4\u0cc1 \u0cb8\u0c82\u0ca7\u0cbf \u0caa\u0cc2\u0c9c\u0cc6.","\u0c85\u0cb7\u0ccd\u0c9f\u0cae\u0ccd\u0caf\u0cbe\u0c82 \u0caa\u0cc2\u0c9c\u0caf\u0cc7\u0ca6\u0ccd\u0ca6\u0cc1\u0cb0\u0ccd\u0c97\u0cbe\u0c82 \u0cb8\u0cb0\u0ccd\u0cb5\u0cae\u0c82\u0c97\u0cb2 \u0cae\u0cbe\u0c82\u0c97\u0cb2\u0ccd\u0caf\u0cc7 |\\n\u0cb6\u0cbf\u0cb5\u0cc7 \u0cb8\u0cb0\u0ccd\u0cb5\u0cbe\u0cb0\u0ccd\u0ca5\u0cb8\u0cbe\u0ca7\u0cbf\u0c95\u0cc7 \u0cb6\u0cb0\u0ca3\u0ccd\u0caf\u0cc7 \u0ca4\u0ccd\u0cb0\u0ccd\u0caf\u0c82\u0cac\u0c95\u0cc7 \u0c97\u0ccc\u0cb0\u0cbf \u0ca8\u0cbe\u0cb0\u0cbe\u0caf\u0ca3\u0cbf \u0ca8\u0cae\u0ccb\u0cbd\u0cb8\u0ccd\u0ca4\u0cc1 \u0ca4\u0cc7 ||","\u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0c85\u0cb7\u0ccd\u0c9f\u0cae\u0cbf \u0cae\u0ca7\u0ccd\u0caf\u0cb0\u0cbe\u0ca4\u0ccd\u0cb0\u0cbf \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1. \u0c85\u0cb7\u0ccd\u0c9f\u0cae\u0cbf-\u0ca8\u0cb5\u0cae\u0cbf \u0cb8\u0c82\u0ca7\u0cbf \u0c95\u0cbe\u0cb2\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0cb8\u0c82\u0ca7\u0cbf \u0caa\u0cc2\u0c9c\u0cc6 \u0c85\u0ca4\u0cbf \u0cb6\u0ccd\u0cb0\u0cc7\u0cb7\u0ccd\u0ca0. \u0ca6\u0cc1\u0cb0\u0ccd\u0c97\u0cbe \u0cb9\u0ccb\u0cae, \u0c9a\u0c82\u0ca1\u0cbf\u0c95\u0cbe \u0caa\u0cc2\u0c9c\u0cc6 \u0cae\u0cbe\u0ca1\u0cac\u0cc7\u0c95\u0cc1.","\u0ca7\u0cb0\u0ccd\u0cae\u0cb8\u0cbf\u0c82\u0ca7\u0cc1 - \u0cae\u0cb9\u0cbe\u0cb7\u0ccd\u0c9f\u0cae\u0cc0 \u0ca8\u0cbf\u0cb0\u0ccd\u0ca3\u0caf (\u0caa\u0cc1. \u0ce7\u0cea\u0ce7)"))
